71	/** 估算工作收入 */
72	function estimateJobPay(job, state) {
73	  // 模拟3次取平均
74	  let total = 0;
75	  for (let i = 0; i < 10; i++) {
76	    total += job.payCalc(state);
77	  }
78	  return Math.floor(total / 10);
79	}
80	
81	// ====== 欢迎界面 ======
82	function showWelcome() {
83	  document.getElementById("app").style.display = "none";
84	  const welcome = document.getElementById("welcome-screen");
85	  welcome.style.display = "flex";
86	
87	  // 更新继续游戏按钮区域
88	  const loadSection = document.getElementById("load-section");
89	  if (loadSection) {
90	    const allSlots = getAllSlots();
91	    if (allSlots.length > 0) {
92	      // 找最新存档
93	      allSlots.sort((a, b) => (b.savedAt || 0) - (a.savedAt || 0));
94	      const latest = allSlots[0];
95	      loadSection.style.display = "";
96	      loadSection.innerHTML = `
97	        <button id="btn-load-latest" class="btn btn-lg">📂 继续游戏 (第${latest.day}天, ¥${latest.cash?.toLocaleString() || 0})</button>
98	        <button id="btn-load-menu" class="btn btn-sm" style="margin-top:8px;">📋 选择存档...</button>
99	      `;
100	      document.getElementById("btn-load-latest").onclick = () =>
101	        loadExistingGame(latest.slot);
102	      document.getElementById("btn-load-menu").onclick = () =>
103	        showLoadMenuOnWelcome();
104	    } else {
105	      loadSection.style.display = "none";
106	    }
107	  }
108	
109	  document.getElementById("btn-new-game").onclick = () => startNewGame();
110	}
111	
112	function startNewGame() {
113	  StateManager.newGame();
114	  initializePrices();
115	  StateManager.addMessage(
116	    "🏘️ 你揣着2000元来到了这座城市。欠村长5500元，日息0.3%。活下去，活出个人样来！",
117	    "event",
118	  );
119	  StateManager.addMessage(
120	    '💡 提示：点击"🗺️ 地图"标签可查看城市全景。在城中村可以租房子、收废品。有了本钱可以去批发市场进货，再到商业区摆摊。',
121	    "info",
122	  );
123	  StateManager.addMessage(
124	    '🚶 点击行动页的"前往 XX"卡片或地图上的地点即可出行。左侧栏也有附近可前往的地点列表。',
125	    "info",
126	  );
127	  document.getElementById("welcome-screen").style.display = "none";
128	  document.getElementById("app").style.display = "";
129	  gameStarted = true;
130	  renderAll();
131	}
132	
133	function loadExistingGame(slot) {
134	  const saveData = loadGame(slot);
135	  if (saveData) {
136	    StateManager.importState(saveData);
137	    StateManager.addMessage("📂 存档已加载，欢迎回来！", "info");
138	    document.getElementById("welcome-screen").style.display = "none";
139	    document.getElementById("app").style.display = "";
140	    gameStarted = true;
141	    renderAll();
142	  }
143	}
