145	/** 欢迎界面上显示存档选择 */
146	function showLoadMenuOnWelcome() {
147	  const allSlots = getAllSlotsWithEmpty();
148	  let bodyHtml = '<div style="max-height:400px;overflow-y:auto;">';
149	  for (const s of allSlots) {
150	    if (s.empty) {
151	      bodyHtml += `<div style="padding:8px;margin:4px 0;background:var(--bg-card);border-radius:4px;opacity:0.4;font-size:12px;color:var(--text-muted);">${s.label} — 空</div>`;
152	    } else {
153	      const phaseLabel = s.phase === "corporate" ? "🏢" : "🏘️";
154	      bodyHtml += `
155	        <div style="padding:10px;margin:4px 0;background:var(--bg-card);border:1px solid var(--border);border-radius:4px;cursor:pointer;transition:all 0.2s;"
156	             onmouseover="this.style.borderColor='var(--accent)'" onmouseout="this.style.borderColor='var(--border)'"
157	             onclick="document.querySelector('.modal-overlay')?.remove();loadExistingGame('${s.slot}')">
158	          <div style="display:flex;justify-content:space-between;align-items:center;">
159	            <strong>${s.label}</strong>
160	            <span style="font-size:11px;color:var(--text-muted)">${s.date}</span>
161	          </div>
162	          <div style="font-size:12px;color:var(--text-secondary);margin-top:4px;">
163	            ${phaseLabel} 第${s.day}天 | 年龄${s.age} | 💰 ¥${s.cash?.toLocaleString() || 0}
164	            ${s.rank ? ` | 🏢 ${s.rank}` : ""}
165	            ${s.debt > 0 ? ` | ⚠️ 欠款 ¥${s.debt.toLocaleString()}` : ""}
166	          </div>
167	        </div>
168	      `;
169	    }
170	  }
171	  bodyHtml += "</div>";
172	
173	  showModal({
174	    title: "📂 读取存档",
175	    body: bodyHtml,
176	    buttons: [{ text: "取消", cls: "", callback: () => {} }],
177	  });
178	}
