180	/** 初始化各地商品价格 */
181	function initializePrices() {
182	  const state = StateManager.getState();
183	  for (const locKey of Object.keys(LOCATIONS)) {
184	    state.trade.goodsPrices[locKey] = {};
185	    const loc = LOCATIONS[locKey];
186	    for (const good of GOODS) {
187	      let price = good.basePrice;
188	      if (loc.priceMod && loc.priceMod[good.id]) {
189	        price *= loc.priceMod[good.id];
190	      }
191	      // 随机波动 ±10%
192	      price *= 0.9 + Math.random() * 0.2;
193	      price = Math.round(price * 100) / 100;
194	      state.trade.goodsPrices[locKey][good.id] = price;
195	    }
196	  }
197	  state.trade.lastPriceUpdate = state.player.day;
198	}
199	
200	// ====== 可用行动列表 ======
201	function getAvailableActions(state) {
202	  const actions = [];
203	
204	  if (state.player.phase === "street") {
205	    // --- 街头阶段行动 ---
206	
207	    // 1. 工作
208	    const locKey = state.trade.currentLocation;
209	    const jobIds = getJobsAtLocation(locKey);
210	    for (const jobId of jobIds) {
211	      const job = getJobById(jobId);
212	      if (!job) continue;
213	      const reqFail = checkJobRequirements(job, state);
214	      const payEstimate = reqFail ? null : estimateJobPay(job, state);
215	
216	      actions.push({
217	        id: "job_" + jobId,
218	        name: job.name,
219	        desc: job.desc,
220	        icon: job.icon,
221	        payEstimate: payEstimate
222	          ? `${payEstimate - (job.startupCost || 0)}~${payEstimate + Math.floor(payEstimate * 0.3)}`
223	          : null,
224	        costEstimate: job.startupCost || null,
225	        reqFail,
226	        disabled:
227	          !!reqFail ||
228	          (job.startupCost && state.resources.cash < job.startupCost
229	            ? `启动资金不足(需¥${job.startupCost})`
230	            : null) ||
231	          null,
232	        handler: () => {
233	          const finalReq = checkJobRequirements(job, state);
234	          if (finalReq) {
235	            StateManager.addMessage(`⚠️ ${finalReq}`, "warning");
236	            return;
237	          }
238	          if (job.startupCost && state.resources.cash < job.startupCost) {
239	            StateManager.addMessage(
240	              `⚠️ 启动资金不足，需要 ¥${job.startupCost}`,
241	              "warning",
242	            );
243	            return;
244	          }
245	          doStreetJob(job);
246	        },
247	      });
248	    }
249	
250	    // 如果没有可用工作
251	    if (jobIds.length === 0) {
252	      actions.push({
253	        id: "no_jobs",
254	        name: "当前地点没有工作机会",
255	        desc: "尝试旅行到其他地点寻找工作。",
256	        icon: "🚫",
257	        disabled: true,
258	      });
259	    }
260	
261	    // 批发市场 — 批发进货
262	    if (locKey === "wholesaleMarket") {
263	      actions.push({
264	        id: "wholesale_header",
265	        name: "📦 批发进货（转到交易Tab）",
266	        desc: "在批发市场以折扣价批量购入商品，转手到商业区卖出赚差价！",
267	        icon: "📦",
268	        handler: () => {
269	          switchTab("trade");
270	        },
271	      });
272	    }
273	
274	    // 零售买卖 — 在任何有价格数据的地点都可以买卖
275	    if (
276	      state.trade.goodsPrices[locKey] &&
277	      Object.keys(state.trade.goodsPrices[locKey]).length > 0
278	    ) {
279	      actions.push({
280	        id: "trade_header",
281	        name: "🛒 买卖商品（转到交易Tab）",
282	        desc: "查看当前市场价格，低买高卖赚取差价。",
283	        icon: "🛒",
284	        handler: () => {
285	          switchTab("trade");
286	        },
287	      });
288	    }
289	
290	    // === 住所系统 ===
291	    if (locKey === "slum") {
292	      const currentTier = state.housing?.tier || 0;
293	      const HOUSING_TIERS = [
294	        {
295	          tier: 0,
296	          name: "露宿街头",
297	          cost: 0,
298	          rent: 0,
299	          capacity: 20,
300	          fatigueRecovery: 15,
301	          desc: "天为被，地为床。碰上刮风下雨就惨了。",
302	          icon: "🌃",
303	        },
304	        {
305	          tier: 1,
306	          name: "合租床位",
307	          cost: 300,
308	          rent: 12,
309	          capacity: 50,
310	          fatigueRecovery: 25,
311	          hygieneBonus: 5,
312	          desc: "城中村合租屋的一个床位，好歹有个遮风挡雨的地方。",
313	          icon: "🛏️",
314	        },
315	        {
316	          tier: 2,
317	          name: "单间",
318	          cost: 800,
319	          rent: 25,
320	          capacity: 100,
321	          fatigueRecovery: 35,
322	          hygieneBonus: 10,
323	          happinessBonus: 5,
324	          desc: "独立小单间，有床有柜子，私密多了。",
325	          icon: "🚪",
326	        },
327	        {
328	          tier: 3,
329	          name: "一居室",
330	          cost: 2000,
331	          rent: 50,
332	          capacity: 200,
333	          fatigueRecovery: 50,
334	          hygieneBonus: 15,
335	          happinessBonus: 10,
336	          desc: "正经的一室一厅，独立卫浴，生活质量质的飞跃。",
337	          icon: "🏠",
338	        },
339	      ];
340	
341	      // 显示当前住所
342	      const curHouse = HOUSING_TIERS[currentTier];
343	      actions.push({
344	        id: "housing_current",
345	        name: `${curHouse.icon} 当前住所：${curHouse.name}`,
346	        desc: `容量+${curHouse.capacity} | 睡眠恢复疲劳-${curHouse.fatigueRecovery} | ${curHouse.desc}${curHouse.rent > 0 ? ` | 日租¥${curHouse.rent}/天` : ""}`,
347	        icon: curHouse.icon,
348	        disabled: true,
349	      });
350	
351	      // 可升级的住所
352	      for (let t = currentTier + 1; t < HOUSING_TIERS.length; t++) {
353	        const house = HOUSING_TIERS[t];
354	        const canAfford = state.resources.cash >= house.cost;
355	        actions.push({
356	          id: "housing_upgrade_" + t,
357	          name: `⬆️ 升级到${house.name}`,
358	          desc: `${house.desc} 一次性付¥${house.cost} + 日租¥${house.rent}/天`,
359	          icon: house.icon,
360	          costEstimate: house.cost,
361	          disabled: !canAfford,
362	          reqFail: !canAfford ? `需 ¥${house.cost}` : null,
363	          handler: () => {
364	            state.resources.cash -= house.cost;
365	            state.housing.tier = t;
366	            state.housing.rentedDay = state.player.day;
367	            state.inventory.capacity =
368	              house.capacity + (state.housing.storageCapacity || 0);
369	            StateManager.addMessage(
370	              `🏠 搬进了${house.name}！容量提升至${state.inventory.capacity}。`,
371	              "success",
372	            );
373	          },
374	        });
375	      }
376	    }
377	
378	    // === 仓库租赁（批发市场）===
379	    if (locKey === "wholesaleMarket") {
380	      const hasStorage = state.housing?.storageRented;
381	      const STORAGE_OPTIONS = [
382	        {
383	          id: "small",
384	          name: "小仓库",
385	          cost: 500,
386	          rent: 20,
387	          capacity: 150,
388	          icon: "📦",
389	        },
390	        {
391	          id: "big",
392	          name: "大仓库",
393	          cost: 1500,
394	          rent: 50,
395	          capacity: 500,
396	          icon: "🏗️",
397	        },
398	      ];
399	
400	      if (hasStorage) {
401	        actions.push({
402	          id: "storage_current",
403	          name: `📦 已租仓库 (额外+${state.housing.storageCapacity || 0}容量)`,
404	          desc: `日租¥${STORAGE_OPTIONS.find((s) => s.capacity === state.housing.storageCapacity)?.rent || "?"}/天`,
405	          icon: "📦",
406	          disabled: true,
407	        });
408	      } else {
409	        for (const opt of STORAGE_OPTIONS) {
410	          const canAfford = state.resources.cash >= opt.cost;
411	          actions.push({
412	            id: "storage_rent_" + opt.id,
413	            name: `📦 租用${opt.name}`,
414	            desc: `额外+${opt.capacity}商品存储容量。一次性¥${opt.cost} + 日租¥${opt.rent}/天`,
415	            icon: opt.icon,
416	            costEstimate: opt.cost,
417	            disabled: !canAfford,
418	            reqFail: !canAfford ? `需 ¥${opt.cost}` : null,
419	            handler: () => {
420	              state.resources.cash -= opt.cost;
421	              state.housing.storageRented = true;
422	              state.housing.storageCapacity = opt.capacity;
423	              const baseCap = [20, 50, 100, 200][state.housing.tier || 0];
424	              state.inventory.capacity = baseCap + opt.capacity;
425	              StateManager.addMessage(
426	                `📦 租下了${opt.name}！总容量提升至${state.inventory.capacity}。`,
427	                "success",
428	              );
429	            },
430	          });
431	        }
432	      }
433	    }
434	
435	    // === 背包升级（商业区）===
436	    if (locKey === "commercialDist") {
437	      const BACKPACKS = [
438	        {
439	          id: "backpack_basic",
440	          name: "帆布背包",
441	          cost: 50,
442	          capacity: 5,
443	          icon: "🎒",
444	        },
445	        {
446	          id: "backpack_large",
447	          name: "大号旅行包",
448	          cost: 150,
449	          capacity: 15,
450	          icon: "🎒",
451	        },
452	        {
453	          id: "backpack_pro",
454	          name: "专业登山包",
455	          cost: 400,
456	          capacity: 30,
457	          icon: "🎒",
458	        },
459	      ];
460	      // 只显示未购买的
461	      const ownedPacks = state.inventory.items.filter((i) =>
462	        i.id.startsWith("backpack_"),
463	      );
464	      for (const pack of BACKPACKS) {
465	        if (ownedPacks.find((p) => p.id === pack.id)) continue;
466	        const canAfford = state.resources.cash >= pack.cost;
467	        actions.push({
468	          id: "buy_" + pack.id,
469	          name: `🛍️ 购买${pack.name}`,
470	          desc: `随身容量+${pack.capacity}。一次性购买，永久拥有。`,
471	          icon: pack.icon,
472	          costEstimate: pack.cost,
473	          disabled: !canAfford,
474	          handler: () => {
475	            state.resources.cash -= pack.cost;
476	            state.inventory.items.push({ id: pack.id, qty: 1 });
477	            state.inventory.capacity += pack.capacity;
478	            StateManager.addMessage(
479	              `🎒 购买了${pack.name}，随身容量+${pack.capacity}！`,
480	              "success",
481	            );
482	          },
483	        });
484	      }
485	    }
486	
487	    // 2. 旅行
488	    const reachable = getReachableLocations(locKey);
489	    for (const destKey of reachable) {
490	      const dest = getLocation(destKey);
491	      if (!dest) continue;
492	      actions.push({
493	        id: "travel_" + destKey,
494	        name: `前往 ${dest.name}`,
495	        desc: dest.desc,
496	        icon: "🚶",
497	        handler: () => {
498	          StateManager.update("trade.currentLocation", destKey);
499	          StateManager.addMessage(`🚶 你来到了${dest.name}。`, "info");
500	        },
501	      });
502	    }
503	
504	    // 3. 通用行动
505	    actions.push({
506	      id: "rest",
507	      name: "休息一会",
508	      desc: "找个地方坐坐，恢复一些疲劳。",
509	      icon: "😴",
510	      handler: () => {
511	        const state = StateManager.getState();
512	        const recovery = 25 + Math.floor(Math.random() * 15);
513	        state.needs.fatigue = Math.max(0, state.needs.fatigue - recovery);
514	        state.needs.happiness = Math.min(100, state.needs.happiness + 5);
515	        StateManager.addMessage(`😴 你休息了一会，疲劳-${recovery}。`, "info");
516	      },
517	    });
518	
519	    actions.push({
520	      id: "eat",
521	      name: "吃顿饭",
522	      desc: "花10元在路边摊吃个快餐，填饱肚子。",
523	      icon: "🍚",
524	      costEstimate: 10,
525	      disabled: state.resources.cash < 10 ? true : false,
526	      handler: () => {
527	        const st = StateManager.getState();
528	        if (st.resources.cash < 10) {
529	          StateManager.addMessage("⚠️ 钱不够吃饭了！", "danger");
530	          return;
531	        }
532	        st.resources.cash -= 10;
533	        st.needs.hunger = Math.min(100, st.needs.hunger + 35);
534	        st.needs.happiness = Math.min(100, st.needs.happiness + 8);
535	        StateManager.addMessage(
536	          "🍚 你花10元吃了顿饭，肚子饱了心情好了。",
537	          "success",
538	        );
539	      },
540	    });
541	
542	    actions.push({
543	      id: "shower",
544	      name: "洗澡",
545	      desc: "花5元去公共澡堂洗个澡。",
546	      icon: "🚿",
547	      costEstimate: 5,
548	      disabled: state.resources.cash < 5 ? true : false,
