983	function addSkillXp(skillKey, amount) {
984	  if (!amount || amount <= 0) return;
985	  const state = StateManager.getState();
986	  const skill = state.skills[skillKey];
987	  if (!skill) return;
988	  skill.xp += amount;
989	  const xpNeeded = (skill.level + 1) * 100;
990	  if (skill.xp >= xpNeeded && skill.level < 100) {
991	    skill.level++;
992	    skill.xp -= xpNeeded;
993	    StateManager.addMessage(
994	      `⭐ ${getSkillName(skillKey)}升级到 Lv.${skill.level}！`,
995	      "success",
996	    );
997	  }
998	}
