38	function renderSidebar(state) {
39	  const p = state.player;
40	
41	  if (p.phase === "street") {
42	    renderStreetStats(state);
43	  } else {
44	    renderCorporateStats(state);
45	  }
46	
47	  renderNeedsBars(state);
48	  renderLocation(state);
49	}
