1	/**
2	 * GameState — 唯一状态源 (Single Source of Truth)
3	 *
4	 * 所有游戏数据集中在此对象中。每个模块通过 getState()/updateState() 读写。
5	 * 使用 Proxy 实现变更追踪（dirty flag），驱动按需渲染。
6	 */
7	
8	// ====== 默认初始状态 ======
9	function createDefaultState() {
10	  const now = Date.now();
11	  return {
12	    // --- 元数据 ---
13	    version: "1.0.0",
14	    createdAt: now,
15	    lastPlayedAt: now,
16	    playTime: 0,
17	
18	    // --- 玩家身份 ---
19	    player: {
20	      name: "无名",
21	      gender: "male",
22	      age: 20,
23	      birthday: { month: 6, day: 15 },
24	
25	      // 街头 4 维属性 (0-100)
26	      physique: 22, // 体质
