.end-screen .end-subtitle {
  font-size: 14px;
  color: var(--text-secondary);
  margin-bottom: 20px;
}

.end-screen.victory .end-title {
  color: var(--success);
}
.end-screen.defeat .end-title {
  color: var(--danger);
}

/* --- Stats Summary Table --- */
.stats-summary {
  width: 100%;
  border-collapse: collapse;
  margin: 16px 0;
}

.stats-summary td {
  padding: 6px 12px;
  font-size: 13px;
  border-bottom: 1px solid var(--border);
}

.stats-summary td:first-child {
  color: var(--text-muted);
}

.stats-summary td:last-child {
  text-align: right;
  font-weight: 600;
}

/* ====== News Banner ====== */
.news-banner {
  background: linear-gradient(135deg, var(--bg-card), rgba(0, 180, 216, 0.08));
  border: 1px solid var(--accent);
  border-left: 3px solid var(--accent);
  border-radius: var(--radius-sm);
  padding: 10px 14px;
  font-size: 12px;
  color: var(--accent);
  flex-shrink: 0;
}

.news-banner .news-icon {
  margin-right: 6px;
}

/* ====== Utility Classes ====== */
.text-success {
  color: var(--success);
}
.text-danger {
  color: var(--danger);
}
.text-warning {
  color: var(--warning);
}
.text-accent {
  color: var(--accent);
}
.text-muted {
  color: var(--text-muted);
}
