/* ====== Event Modal (Random Story Event) ====== */
.event-box {
  min-width: 380px;
  max-width: 540px;
  border-top: 4px solid var(--accent);
  background: linear-gradient(180deg, var(--bg-secondary), var(--bg-card));
}

.event-header {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 14px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--border);
}

.event-icon {
  font-size: 40px;
  width: 56px;
  height: 56px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: radial-gradient(circle, rgba(0, 180, 216, 0.15), transparent);
  border-radius: 50%;
  flex-shrink: 0;
}

.event-title {
  font-size: 18px;
  color: var(--accent);
  margin: 0;
}

.event-story {
  font-size: 13px;
  color: var(--text-primary);
  line-height: 1.7;
  margin-bottom: 16px;
  padding: 12px 14px;
  background: var(--bg-card);
  border-left: 3px solid var(--accent);
  border-radius: var(--radius-sm);
}

.event-choices {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.event-choice {
  display: block;
  width: 100%;
  text-align: left;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 10px 14px;
  color: var(--text-primary);
  font-size: 13px;
  cursor: pointer;
  transition: all 0.15s ease;
  position: relative;
}

.event-choice:hover:not(.disabled) {
  background: var(--bg-card-hover, rgba(0, 180, 216, 0.08));
  border-color: var(--accent);
  transform: translateX(2px);
}

.event-choice.disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.event-choice .choice-main {
  font-weight: 600;
  color: var(--text-primary);
}

.event-choice .choice-hint {
  font-size: 11px;
  color: var(--text-muted);
  margin-top: 3px;
}

/* 弹窗进入动画 */
@keyframes eventPop {
  0% {
    transform: scale(0.85) translateY(-20px);
    opacity: 0;
  }
  100% {
    transform: scale(1) translateY(0);
    opacity: 1;
  }
}

.event-overlay,
.modal-overlay.event-modal {
  animation: fadeIn 0.2s ease;
}

.event-overlay .modal-box,
.modal-overlay.event-modal .modal-box {
  animation: eventPop 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}

/* ====== Utility Classes ====== */
.text-success {
  color: var(--success);
}

