516	// ====== Map Tab ======
517	function renderMapTab(state, parent) {
518	  const locKey = state.trade.currentLocation;
519	  const loc = getLocation(locKey);
520	
521	  const container = document.createElement("div");
522	  container.style.cssText = "display:flex;flex-direction:column;gap:16px;";
523	
524	  // 标题
525	  const title = document.createElement("div");
526	  title.innerHTML = `
527	    <h3 style="color:var(--text-muted);margin-bottom:4px;">🗺️ 城市地图</h3>
528	    <p style="font-size:12px;color:var(--text-secondary);">
529	      当前在 <strong style="color:var(--accent);">${loc ? loc.name : "未知"}</strong> — 点击地点直接前往（仅显示已探索的相邻地点可到达的）
530	    </p>
531	  `;
532	  container.appendChild(title);
533	
534	  // 城市地图 — 使用 CSS Grid 布局，按地理关系排列
535	  const mapWrap = document.createElement("div");
536	  mapWrap.className = "city-map";
537	  mapWrap.style.cssText =
538	    "position:relative;background:var(--bg-card);border:1px solid var(--border);border-radius:var(--radius-lg);padding:24px;min-height:500px;overflow:auto;";
539	
540	  // 地图网格（用绝对定位模拟地理位置）
541	  const mapGrid = document.createElement("div");
542	  mapGrid.style.cssText = "position:relative;width:100%;min-height:460px;";
543	
544	  // 地点坐标映射（百分比定位）
545	  const positions = {
546	    techPark: { x: 65, y: 5 },
547	    commercialDist: { x: 58, y: 22 },
548	    wholesaleMarket: { x: 28, y: 18 },
549	    construction: { x: 70, y: 38 },
550	    factoryZone: { x: 35, y: 40 },
551	    hospital: { x: 78, y: 30 },
552	    slum: { x: 30, y: 55 },
553	    bank: { x: 12, y: 50 },
554	    park: { x: 50, y: 62 },
555	    school: { x: 42, y: 72 },
556	    trainingCenter: { x: 55, y: 85 },
557	  };
558	
559	  // SVG连线
560	  const svgNS = "http://www.w3.org/2000/svg";
561	  const svg = document.createElementNS(svgNS, "svg");
562	  svg.style.cssText =
563	    "position:absolute;top:0;left:0;width:100%;height:100%;pointer-events:none;z-index:1;";
564	  mapGrid.appendChild(svg);
565	
566	  // 延迟绘制连线（需要等节点渲染后获取位置）
567	  const drawConnections = () => {
568	    svg.innerHTML = "";
569	    const mapRect = mapGrid.getBoundingClientRect();
570	    for (const [from, toList] of Object.entries(TRAVEL_GRAPH)) {
571	      const fromEl = mapGrid.querySelector(`[data-map-loc="${from}"]`);
572	      if (!fromEl) continue;
573	      for (const to of toList) {
574	        const toEl = mapGrid.querySelector(`[data-map-loc="${to}"]`);
575	        if (!toEl) continue;
576	        const fromRect = fromEl.getBoundingClientRect();
577	        const toRect = toEl.getBoundingClientRect();
578	        const x1 = fromRect.left + fromRect.width / 2 - mapRect.left;
579	        const y1 = fromRect.top + fromRect.height / 2 - mapRect.top;
580	        const x2 = toRect.left + toRect.width / 2 - mapRect.left;
581	        const y2 = toRect.top + toRect.height / 2 - mapRect.top;
582	        const line = document.createElementNS(svgNS, "line");
583	        line.setAttribute("x1", x1);
584	        line.setAttribute("y1", y1);
585	        line.setAttribute("x2", x2);
586	        line.setAttribute("y2", y2);
587	        line.setAttribute("stroke", "rgba(0,180,216,0.2)");
588	        line.setAttribute("stroke-width", "1.5");
589	        line.setAttribute("stroke-dasharray", "4,3");
590	        svg.appendChild(line);
591	      }
592	    }
593	  };
594	
595	  // 检查从当前位置可达的地点
596	  const reachable = new Set(getReachableLocations(locKey));
597	  reachable.add(locKey); // 当前位置也算"可达"（高亮）
598	
599	  // 放置节点
600	  for (const [key, pos] of Object.entries(positions)) {
601	    const mapLoc = getLocation(key);
602	    if (!mapLoc) continue;
603	    const badges = getLocationServiceBadges(key);
